<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';const form=reactive({password:''});function submit(){router.post('/admin/login',form)}</script>
<template><main class="grid min-h-screen place-items-center bg-cream px-5"><form @submit.prevent="submit" class="w-full max-w-sm rounded-3xl bg-white/60 p-8 shadow-xl"><div class="serif text-3xl font-bold">Daily Dough Admin</div><p class="mt-2 text-sm opacity-60">Enter the admin password.</p><input v-model="form.password" type="password" placeholder="Password" class="mt-7 w-full rounded-2xl border border-brown/15 bg-white px-4 py-3"><button class="mt-4 w-full rounded-full bg-brown py-3 font-bold text-cream">Sign in</button></form></main></template>
